 // [ ESAME 2023-01-11
 /// @ingroup esame

-	//sem_wait(d->mutex);
-	//starthd_in(d, vetti, primo, quanti);
-	//sem_wait(d->sincr);
-	//sem_signal(d->mutex);
+	sem_wait(d->mutex);
+	for (int i = 0; i < quanti; i++) {
+		natl block_num = primo + i;
+		natb* user_buf = vetti + i * DIM_BLOCK;
+
+		buf_des* cached = nullptr;
+		for (int j = 0; j < MAX_BUF_DES; j++) {
+			if (d->bufcache[j].full && d->bufcache[j].block == block_num) {
+				cached = &d->bufcache[j];
+				break;
+			}
+		}

-/// @todo Gestire l'operazione tenendo conto della buffer cache.
-// ( SOLUZIONE 2023-01-11
-//   SOLUZIONE 2023-01-11 )
+		if (cached) {
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				user_buf[j] = cached->buf[j];
+			bufcache_promote(cached);
+		} else {
+			buf_des* target = nullptr;
+			for (int j = 0; j < MAX_BUF_DES; j++) {
+				if (!d->bufcache[j].full) {
+					target = &d->bufcache[j];
+					break;
+				}
+			}
+			if (!target) {
+				target = &d->bufcache[d->lru];
+				if (target->next >= 0)
+					d->bufcache[target->next].prev = target->prev;
+				else
+					d->mru = target->prev;
+				d->lru = target->next;
+				target->prev = -1;
+				target->next = -1;
+			}
+
+			target->block = block_num;
+			target->full = true;
+
+			starthd_in(d, target->buf, block_num, 1);
+			sem_wait(d->sincr);
+
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				user_buf[j] = target->buf[j];
+
+			bufcache_promote(target);
+		}
+	}
+	sem_signal(d->mutex);
 //   ESAME 2023-01-11 ]
 }
