+	sem_wait(d->mutex);
+	for (int i = 0; i < quanti; i++) {
+		natl block_num = primo + i;
+		natb* user_buf = vetto + i * DIM_BLOCK;
+
+		buf_des* cached = nullptr;
+		for (int j = 0; j < MAX_BUF_DES; j++) {
+			if (d->bufcache[j].full && d->bufcache[j].block == block_num) {
+				cached = &d->bufcache[j];
+				break;
+			}
+		}
+
+		if (cached) {
+			for (natq j = 0; j < DIM_BLOCK; j++)
+				cached->buf[j] = user_buf[j];
+			bufcache_promote(cached);
+			starthd_out(d, cached->buf, block_num, 1);
+			sem_wait(d->sincr);
+		} else {
+			starthd_out(d, user_buf, block_num, 1);
+			sem_wait(d->sincr);
+		}
+	}
+	sem_signal(d->mutex);
 //   ESAME 2023-01-11 ]
 }
 /// @}
@@ -734,8 +793,13 @@ bool hd_init()

 	hd::enable_intr();

-// ( SOLUZIONE 2023-01-11
-//   SOLUZIONE 2023-01-11 )
+	d->lru = -1;
+	d->mru = -1;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		d->bufcache[i].full = false;
+		d->bufcache[i].next = -1;
+		d->bufcache[i].prev = -1;
+	}

 	return true;
 }
